void verifyDataSourceContract(DataSource ds) throws SQLException {
  Connection c = ds.getConnection();
  assert c != null;
  assert !c.isClosed();
  c.close();
  assert c.isClosed();
  System.out.println("kontrakt OK");
}

class CircuitBreakerDataSource implements DataSource {
  private int failures = 0;
  public Connection getConnection() throws SQLException {
    if (failures >= 3) throw new SQLException("Circuit open");
    try { return delegate.getConnection(); }
    catch (SQLException e) { failures++; throw e; }
  }
  void reset() { failures = 0; }
}

